import { useState } from "react";
import { useApp } from "../../context/AppContext";
import { EmptyState } from "../../components/UI";
import { Pill } from "../../components/UI";

export function IlanVerSayfasi() {
  const { ilanEkle } = useApp();
  const [form, setForm] = useState({
    nereden: "", nereye: "", yuk: "",
    tonSecim: "20", // 1-50 veya serbest
    ucret: "", tarih: "",
    aracTip: "", aciklama: "", odemeTuru: "pesin", odemeGun: 0
  });
  const [tamam, setTamam] = useState(false);
  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const gonder = () => {
    if (!form.nereden || !form.nereye || !form.yuk || !form.ucret) return;
    const ton = form.tonSecim === "serbest" ? 0 : Number(form.tonSecim);
    ilanEkle({
      ...form,
      ton: ton,
      ucret: Number(form.ucret),
      odemeTuru: form.odemeTuru,
      odemeGun: Number(form.odemeGun)
    });
    setTamam(true);
    setTimeout(() => {
      setTamam(false);
      setForm({
        nereden: "", nereye: "", yuk: "",
        tonSecim: "20", ucret: "", tarih: "",
        aracTip: "", aciklama: "", odemeTuru: "pesin", odemeGun: 0
      });
    }, 2000);
  };

  const inputStyle = "input";
  const Label = ({ children, zorunlu }) => (
    <label className="label">{children} {zorunlu && <span style={{ color: "var(--turuncu)" }}>*</span>}</label>
  );

  if (tamam) return (
    <div className="scroll-content" style={{ display: "flex", alignItems: "center", justifyContent: "center", minHeight: 400 }}>
      <div style={{ textAlign: "center" }}>
        <div style={{ fontSize: 52, marginBottom: 16 }}>✅</div>
        <div className="display" style={{ fontSize: 28, color: "var(--yesil)" }}>İLAN YAYINDA!</div>
        <div style={{ color: "var(--text3)", marginTop: 8 }}>Teklifler gelmeye başlayacak</div>
      </div>
    </div>
  );

  return (
    <div className="scroll-content">
      <div className="section-title">YENİ İLAN VER</div>

      <div className="card" style={{ marginBottom: 12 }}>
        <div className="label" style={{ marginBottom: 14 }}>🗺️ Güzergah</div>
        <div className="input-row">
          <div className="input-group">
            <Label zorunlu>Nereden</Label>
            <input className={inputStyle} placeholder="Antalya" value={form.nereden} onChange={e => set("nereden", e.target.value)} />
          </div>
          <div className="input-group">
            <Label zorunlu>Nereye</Label>
            <input className={inputStyle} placeholder="İzmir" value={form.nereye} onChange={e => set("nereye", e.target.value)} />
          </div>
        </div>
      </div>

      <div className="card" style={{ marginBottom: 12 }}>
        <div className="label" style={{ marginBottom: 14 }}>📦 Yük Bilgisi</div>
        <div className="input-group">
          <Label zorunlu>Yük Türü</Label>
          <input className={inputStyle} placeholder="Kömür, çelik, gıda..." value={form.yuk} onChange={e => set("yuk", e.target.value)} />
        </div>
        <div className="input-row">
          <div className="input-group">
            <Label>Tonaj Seçimi</Label>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              {[1, 5, 10, 15, 20, 25, 30, 40, 50, "serbest"].map(t => (
                <button
                  key={t}
                  onClick={() => set("tonSecim", t)}
                  style={{
                    padding: "10px 14px",
                    borderRadius: "var(--r)",
                    border: `2px solid ${form.tonSecim === t ? "var(--turuncu)" : "var(--border)"}`,
                    background: form.tonSecim === t ? "rgba(232,82,10,0.1)" : "transparent",
                    color: form.tonSecim === t ? "var(--turuncu)" : "var(--text2)",
                    fontSize: 13,
                    fontWeight: 600,
                    cursor: "pointer"
                  }}
                >
                  {t === "serbest" ? "Serbest" : `${t} Ton`}
                </button>
              ))}
            </div>
            <div style={{ fontSize: 11, color: "var(--text3)", marginTop: 6 }}>
              Tonaj: {form.tonSecim === "serbest" ? "Serbest (Belirtilmedi)" : `${form.tonSecim} Ton`}
            </div>
          </div>
          <div className="input-group">
            <Label zorunlu>Ücret (₺)</Label>
            <input className={inputStyle} type="number" placeholder="8500" value={form.ucret} onChange={e => set("ucret", e.target.value)} />
          </div>
        </div>
        <div className="input-group">
          <Label>Araç Tipi</Label>
          <select className={inputStyle} value={form.aracTip} onChange={e => set("aracTip", e.target.value)} style={{ cursor: "pointer" }}>
            <option value="">Seçin...</option>
            {["TIR / Kapalı Kasa", "Frigorifik TIR", "Flatbed / Lowbed", "Tenteli TIR", "Damperli TIR", "Tanker", "Konteyner"].map(t => <option key={t}>{t}</option>)}
          </select>
        </div>
      </div>

      <div className="card" style={{ marginBottom: 12 }}>
        <div className="label" style={{ marginBottom: 14 }}>📅 Tarih & Notlar</div>
        <div className="input-group">
          <Label>Yükleme Tarihi</Label>
          <input className={inputStyle} type="date" value={form.tarih} onChange={e => set("tarih", e.target.value)} />
        </div>
        <div className="input-group">
          <Label>Açıklama</Label>
          <textarea className={inputStyle} rows={3} placeholder="Özel şartlar, araç özellikleri..." value={form.aciklama} onChange={e => set("aciklama", e.target.value)} style={{ resize: "vertical", lineHeight: 1.6 }} />
        </div>
      </div>

      {/* Ödeme Planı Seçimi */}
      <div className="card" style={{ marginBottom: 12 }}>
        <div className="label" style={{ marginBottom: 12 }}>💰 Ödeme Planı Seçin</div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr", gap: 8 }}>
          {[
            { tur: "pesin", gun: 0, label: "Peşin", desc: "Hemen tam ödeme", color: "var(--yesil)" },
            { tur: "7-gun", gun: 7, label: "7 Gün", desc: "Teslimden 7 gün sonra", color: "var(--kirmizi)" },
            { tur: "15-gun", gun: 15, label: "15 Gün", desc: "Teslimden 15 gün sonra", color: "var(--sari)" },
            { tur: "30-gun", gun: 30, label: "30 Gün", desc: "Teslimden 30 gün sonra", color: "var(--mavi)" },
          ].map(opt => (
            <button
              key={opt.tur}
              onClick={() => set("odemeTuru", opt.tur)}
              style={{
                padding: "12px",
                borderRadius: "var(--r)",
                border: `2px solid var(--border)`,
                background: "transparent",
                color: "var(--text2)",
                fontSize: 13,
                fontWeight: 600,
                cursor: "pointer",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: 4
              }}
            >
              <div style={{ fontSize: 20 }}>{opt.color === "var(--yesil)" ? "💰" : opt.color === "var(--kirmizi)" ? "⚡" : opt.color === "var(--sari)" ? "⏰" : "📅"}</div>
              <div style={{ color: opt.color }}>{opt.label}</div>
              <div style={{ fontSize: 9, color: "var(--text3)" }}>{opt.desc}</div>
            </button>
          ))}
        </div>
      </div>

      <button onClick={gonder} className="btn btn-primary btn-full" style={{ padding: "16px" }}>
        📢 İLANI YAYINLA
      </button>
    </div>
  );
}

export function TekliflerSayfasi() {
  const { teklifler = [] } = useApp();
  const bekleyenTeklifler = teklifler.filter(t => t.durum === "bekliyor");

  return (
    <div className="scroll-content">
      <div className="section-title">TEKLİFLERIM ({bekleyenTeklifler.length})</div>
      {bekleyenTeklifler.length === 0 ? (
        <EmptyState icon="📋" text="Henüz teklif yok" />
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {bekleyenTeklifler.map((t, i) => (
            <div key={i} className="card" style={{ display: "flex", alignItems: "center", gap: 12, border: "1px solid var(--border)" }}>
              <div style={{ width: 42, height: 42, borderRadius: "50%", background: "var(--bg3)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18, flexShrink: 0 }}>🚛</div>
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 600, fontSize: 14 }}>{t.kamyoncu || t}</div>
                <div style={{ fontSize: 12, color: "var(--text3)" }}>₺{t.ucret.toLocaleString()}</div>
              </div>
              <button className="btn btn-primary" style={{ padding: "8px 16px", fontSize: 12 }}>Kabul Et</button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export function MesajlarSayfasi() {
  const mesajlar = [
    { ad: "Metro Gıda Lojistik", son: "Teslim evrağını gördük, ödeme yapılıyor.", zaman: "14:32", okunmadi: 1 },
    { ad: "Mevlüt Taşıma A.Ş.", son: "Harika, görüşürüz!", zaman: "Dün", okunmadi: 0 },
    { ad: "Akdeniz Tarım", son: "Fiyat için müsait misiniz?", zaman: "Dün", okunmadi: 1 },
  ];
  return (
    <div className="scroll-content">
      <div className="section-title">MESAJLAR</div>
      {mesajlar.map((m, i) => (
        <div key={i} className="card" style={{ marginBottom: 8, display: "flex", alignItems: "center", gap: 12, cursor: "pointer" }}>
          <div style={{ width: 42, height: 42, borderRadius: "50%", background: "var(--bg3)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18, flexShrink: 0 }}>🏢</div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontWeight: 600, fontSize: 14 }}>{m.ad}</div>
            <div style={{ fontSize: 12, color: "var(--text3)", marginTop: 2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{m.son}</div>
          </div>
          <div style={{ flexShrink: 0, textAlign: "right" }}>
            <div style={{ fontSize: 11, color: "var(--text3)" }}>{m.zaman}</div>
            {m.okunmadi > 0 && <div style={{ marginTop: 4, background: "var(--turuncu)", color: "#fff", borderRadius: "50%", width: 18, height: 18, fontSize: 10, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", marginLeft: "auto" }}>{m.okunmadi}</div>}
          </div>
        </div>
      ))}
    </div>
  );
}

export function IssizProfilSayfasi() {
  const { oturum, cikisYap } = useApp();
  return (
    <div className="scroll-content">
      <div className="card" style={{ textAlign: "center", padding: 24, marginBottom: 12 }}>
        <div style={{ fontSize: 52, marginBottom: 10 }}>🏢</div>
        <div className="display" style={{ fontSize: 28 }}>{oturum?.ad || "Demo Firma"}</div>
        <div className="rating" style={{ marginTop: 6 }}>⭐ 4.9 — Güvenilir İşveren</div>
        <div style={{ marginTop: 14, fontSize: 12, color: "var(--text3)" }}>Firma • İstanbul</div>
        <div className="stat-grid" style={{ marginTop: 16 }}>
          <div className="stat-box"><div className="stat-val">47</div><div className="stat-lbl">İlan</div></div>
          <div className="stat-box"><div className="stat-val">89</div><div className="stat-lbl">Sefer</div></div>
          <div className="stat-box"><div className="stat-val">4.8</div><div className="stat-lbl">Puan</div></div>
        </div>
      </div>

      <div className="card" style={{ marginBottom: 12 }}>
        <div className="label" style={{ marginBottom: 12 }}>📁 Belgelerim</div>
        {[
          { ad: "Firma Kayıt Belgesi", ok: true },
          { ad: "Vergi Levhası", ok: true },
          { ad: "İş Yeri Güvenliği", ok: true },
        ].map((b, i) => (
          <div key={i} style={{ background: "var(--bg2)", borderRadius: "var(--r)", padding: "10px 12px", marginBottom: 6, display: "flex", alignItems: "center", gap: 8 }}>
            {b.ok ? "✓" : "○"}
            <span style={{ fontSize: 13 }}>{b.ad}</span>
          </div>
        ))}
        <button className="btn btn-secondary" style={{ width: "100%", marginTop: 12, fontSize: 13 }}>
          + Yeni Belge Ekle
        </button>
      </div>

      {["Banka Hesabım", "Bildirim Ayarları", "Yardım & Destek", "Gizlilik Politikası"].map(item => (
        <div key={item} className="card" style={{ marginBottom: 8, display: "flex", justifyContent: "space-between", alignItems: "center", cursor: "pointer" }}>
          <span style={{ fontSize: 14 }}>{item}</span>
          <span style={{ color: "var(--text3)" }}>›</span>
        </div>
      ))}

      <button onClick={cikisYap} className="btn btn-secondary btn-full" style={{ marginTop: 8 }}>
        Çıkış Yap
      </button>
    </div>
  );
}
